    "contacts.type_internal": "Ichki",
    "costmodel.evm_live": "Jonli",
    "costmodel.evm_live_tooltip": "Jonli - xarajat, jadval bajarilishi yoki moliya maʼlumotlari oʻzgarganda bu koʻrsatkichlar avtomatik yangilanadi",
    "nav.capacity_planning": "Sigʻim rejalashtirish",
